const x=$input.first().json;
const tests=x._tests||[];
const pushTest=(id,name,status,msg,evidence)=>{tests.push({test_id:id,name,status,message:msg,evidence:evidence||null});};

if(!x._parse_ok){
    pushTest('STATIC_EXPR','Expressions check','skipped','Skipped: parse failed',null);
    return [{json:{...x,_tests:tests}}];
}

const wf=x._parsed_wf;
const nodes=Array.isArray(wf.nodes)?wf.nodes:[];
const issues=[];

function checkExpressions(obj, nodeName) {
    if (!obj) return;
    if (typeof obj === 'string') {
        const opens = (obj.match(/\{\{/g) || []).length;
        const closes = (obj.match(/\}\}/g) || []).length;
        if (opens !== closes) issues.push(nodeName + ': ' + opens + ' open, ' + closes + ' close');
    } else if (Array.isArray(obj)) {
        for (const item of obj) checkExpressions(item, nodeName);
    } else if (typeof obj === 'object') {
        for (const key of Object.keys(obj)) checkExpressions(obj[key], nodeName);
    }
}

for(const n of nodes){
    if(!n||!n.parameters)continue;
    checkExpressions(n.parameters, n.name);
}

if(issues.length===0)pushTest('STATIC_EXPR','Expressions check','passed','All parameter expressions have balanced {{ }}',null);
else pushTest('STATIC_EXPR','Expressions check','failed',issues.slice(0,5).join('; '),null);

return [{json:{...x,_tests:tests}}];

const x = $('Test Supported Features').first()?.json || $input.first()?.json || {};
const tests = Array.isArray(x._tests) ? [...x._tests] : [];
const pushTest = (id, name, status, msg, evidence) => {
  tests.push({ test_id: id, name, status, message: msg, evidence: evidence || null });
};

const mode = x.test_mode;
const run = (mode === 'runtime' || mode === 'full');
const authorized = x.test_environment_authorized === true;

let runtimeEndpoint = null;
try {
  runtimeEndpoint = $env?.WF04_RUNTIME_ENDPOINT || null;
} catch (e) {}

const endpointConfigured = !!(runtimeEndpoint && String(runtimeEndpoint).trim());

if (!run) {
  pushTest('RUNTIME_GATE', 'Runtime eligibility', 'not_requested', 'test_mode=' + mode, null);
  return [{ json: { ...x, _tests: tests, _runtime_eligible: false, _runtime_reason: 'test_mode=' + mode } }];
}
if (!authorized) {
  pushTest('RUNTIME_GATE', 'Runtime eligibility', 'skipped', 'test_environment_authorized=false — runtime skipped', null);
  return [{ json: { ...x, _tests: tests, _runtime_eligible: false, _runtime_reason: 'not_authorized' } }];
}
if (!endpointConfigured) {
  pushTest('RUNTIME_GATE', 'Runtime eligibility', 'not_requested', 'authorized=true but WF04_RUNTIME_ENDPOINT not configured — endpoint integration pending', null);
  return [{ json: { ...x, _tests: tests, _runtime_eligible: false, _runtime_reason: 'endpoint_not_configured' } }];
}

pushTest('RUNTIME_GATE', 'Runtime eligibility', 'passed', 'Test environment authorized + endpoint configured', null);
return [{ json: { ...x, _tests: tests, _runtime_eligible: true, _runtime_reason: 'authorized' } }];

const base = $('Check Runtime Eligibility').first()?.json || {};
const inp = $input.first()?.json || {};
const x = (Array.isArray(inp._tests) && inp._tests.length > 0) ? inp : base;
const tests = Array.isArray(x._tests) ? [...x._tests] : [];

tests.push({ test_id: 'RUNTIME_EXEC', name: 'Runtime execution', status: 'skipped', message: 'Runtime execution endpoint configured but integration pending', evidence: 'External n8n test environment integration' });
tests.push({ test_id: 'RUNTIME_LOGS', name: 'Execution logs', status: 'skipped', message: 'Runtime logs unavailable', evidence: null });
tests.push({ test_id: 'RUNTIME_EXPECTED', name: 'Expected output', status: 'skipped', message: 'Expected output not provided', evidence: null });
tests.push({ test_id: 'RUNTIME_FAILURE', name: 'Failure analysis', status: 'skipped', message: 'Runtime failure analysis not available', evidence: null });

return [{ json: { ...x, _tests: tests, _runtime_executed: false } }];

const base = $('Check Runtime Eligibility').first()?.json || {};
const inp = $input.first()?.json || {};
const x = (Array.isArray(inp._tests) && inp._tests.length > 0) ? inp : base;
const tests = Array.isArray(x._tests) ? [...x._tests] : [];

const mode = x.test_mode;
const run = (mode === 'runtime' || mode === 'full');
const reason = x._runtime_reason || 'not_authorized';

if (run) {
  tests.push({ test_id: 'RUNTIME_EXEC', name: 'Runtime execution', status: 'skipped', message: 'Runtime tests skipped: ' + reason, evidence: 'Blueprint: runtime only when authorized env available' });
  tests.push({ test_id: 'RUNTIME_LOGS', name: 'Execution logs', status: 'skipped', message: 'Runtime logs unavailable', evidence: null });
  tests.push({ test_id: 'RUNTIME_EXPECTED', name: 'Expected output', status: 'skipped', message: 'Expected output not provided', evidence: null });
  tests.push({ test_id: 'RUNTIME_FAILURE', name: 'Failure analysis', status: 'skipped', message: 'Runtime failure analysis not available', evidence: null });
} else {
  tests.push({ test_id: 'RUNTIME_EXEC', name: 'Runtime execution', status: 'not_requested', message: 'test_mode=' + mode, evidence: null });
  tests.push({ test_id: 'RUNTIME_LOGS', name: 'Execution logs', status: 'not_requested', message: 'test_mode=' + mode, evidence: null });
  tests.push({ test_id: 'RUNTIME_EXPECTED', name: 'Expected output', status: 'not_requested', message: 'test_mode=' + mode, evidence: null });
  tests.push({ test_id: 'RUNTIME_FAILURE', name: 'Failure analysis', status: 'not_requested', message: 'test_mode=' + mode, evidence: null });
}

return [{ json: { ...x, _tests: tests, _runtime_executed: false } }];

const inp = $input.first()?.json || {};
const base = $('Check Runtime Eligibility').first()?.json || {};
const x = (Array.isArray(inp._tests) && inp._tests.length >= (base._tests?.length || 0)) ? inp : base;

return [{ json: { ...x, _runtime_normalized: true } }];

const x = $('Normalize Runtime Results').first()?.json || $input.first()?.json || {};
const tests = Array.isArray(x._tests) ? x._tests : [];

const reqId = $('Validate Request').first()?.json?.request_id || x.request_id || 'fallback-id';
const testId = 'TST-' + reqId;

const seen = new Set();
const unique = [];
for (const t of tests) {
  if (!t || !t.test_id) continue;
  if (seen.has(t.test_id)) continue;
  seen.add(t.test_id);
  unique.push(t);
}

return [{ json: { ...x, request_id: reqId, _tests: unique, _test_id: testId } }];

const x=$input.first().json;
const a=x._aggregate||{};
const wf=x._parsed_wf;
let nodeCount=0;
if(wf&&Array.isArray(wf.nodes))nodeCount=wf.nodes.filter(n=>n&&typeof n==='object').length;

const reqId = $('Validate Request').first()?.json?.request_id || x.request_id || 'fallback-id';

const result={
    test_id:'TST-'+reqId,
    validation_status:a.validation_status||'failed',
    tests_executed:(a.executed||[]).map(t=>({test_id:t.test_id,name:t.name,status:t.status,message:t.message})),
    passed_tests:(a.passed||[]).map(t=>t.test_id),
    failed_tests:(a.failed||[]).map(t=>({test_id:t.test_id,name:t.name,message:t.message})),
    skipped_tests:(a.skipped||[]).map(t=>({test_id:t.test_id,name:t.name,message:t.message})),
    not_requested_tests:(a.notRequested||[]).map(t=>({test_id:t.test_id,name:t.name,message:t.message})),
    evidence:a.evidence||[],
    limitations:a.limitations||[],
    test_mode:x.test_mode||null,
    target_n8n_version:x.target_n8n_version||null,
    workflow_hash:x.workflow_hash||null,
    node_count:nodeCount,
    redacted_fields:[],
    counts:{executed:(a.executed||[]).length,passed:(a.passed||[]).length,failed:(a.failed||[]).length,skipped:(a.skipped||[]).length,not_requested:(a.notRequested||[]).length},
    verification_summary:{status:'not_verified',evidence:a.evidence||[],runtime_verified:false,compatibility_verified:false}
};

const status=a.validation_status||'failed';
const httpStatus=status==='failed'?422:200;
const errors=(a.failed||[]).length>0?[{category:'VALIDATION_FAILED',message:(a.failed||[]).length+' test(s) failed',details:(a.failed||[]).slice(0,10).map(t=>t.test_id+': '+t.message)}]:[];
const warnings=(a.skipped||[]).length>0?[{message:(a.skipped||[]).length+' test(s) skipped; they are NOT counted as passed'}]:[];

return [{json:{
    request_id:reqId,
    task_id:null,
    status:status==='passed'?'completed':(status==='partial'?'partial':'failed'),
    _http_status:httpStatus,
    result,
    errors,
    warnings,
    verification:result.verification_summary,
    _persist:{
        project_id:x.project_id,
        user_id:x.user_id,
        claimed_user_id:x.user_id,
        workspace_id:x.workspace_id,
        conversation_id:x.conversation_id,
        workflow_id:x.workflow_id||null,
        workflow_name:x.workflow_name||null,
        test_id:result.test_id,
        test_mode:x.test_mode,
        node_count:nodeCount,
        event_type:'skill_executed'
    }
}}];
